+  select count(*) filter(where state='SENDING'),
+         count(*) filter(where state='PREPARED')
+    into v_sending,v_remaining from jaspic_isolated_test.deliveries;
+  if v_claimed<>10 or v_sending<>10 or v_remaining<>24 then
